            file_read: fileReadMock,
            file_write: function(arg1, arg2) {
                if (typeof arg1 === 'string') {
                    written.push({ path: arg1, content: arg2 });
                } else {
                    written.push({ path: arg1.path, content: arg1.content });
                }
            },
            jira_search_by_jql: function(search) {
