function makeJqlDispatch(routes) {
    return function(args) {
        for (var i = 0; i < routes.length; i++) {
            var route = routes[i];
            var matches = route.contains.every(function(fragment) {
                return args.jql.indexOf(fragment) !== -1;
            });
            if (matches) return route.result;
        }
        return [];
